<template><el-timeline v-if="history?.length"><el-timeline-item v-for="e in history" :key="e.id" :timestamp="new Date(e.createdAt).toLocaleString('vi-VN')"><b>{{labels[e.toStatus]||e.toStatus}}</b> — {{e.note}}<div v-if="showActor">{{e.actor}}</div></el-timeline-item></el-timeline><p v-else>Đơn cũ chưa có nhật ký xử lý.</p></template><script setup>defineProps({history:Array,showActor:Boolean});const labels={PENDING_PAYMENT:'Chờ thanh toán',CONFIRMED:'Chờ xử lý (COD)',PAID:'Đã thanh toán',PREPARING:'Đang chuẩn bị',SHIPPING:'Đang giao',DELIVERED:'Đã giao',COMPLETED:'Hoàn thành',CANCELLED:'Đã hủy',EXPIRED:'Hết hạn'};</script>